mapper.select:
select role
  from trip_member
 where trip_id = #{tripId}
   and user_id = #{userId}
   and status = 'JOINED'

mapper.update:
update trip
   set title = #{title}
 where trip_id = #{tripId}
   and del_yn = 'N'

update trip
   set start_date = #{startDate, jdbcType=DATE}
 where trip_id = #{tripId}
   and del_yn = 'N'

update trip
   set scope = #{scope}
 where trip_id = #{tripId}
   and del_yn = 'N'

update trip
   set del_yn = 'Y'
 where trip_id = #{tripId}

mapper.select:
select count(*)
  from schedule s
  join trip_day d on d.day_id = s.day_id
 where d.trip_id = #{tripId}
   and d.day_no <= #{dayNo}

select count(*)
  from schedule s
  join trip_day d on d.day_id = s.day_id
 where d.trip_id = #{tripId}
   and d.day_no > #{dayNo}
